/* @lc app=leetcode id=3378 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = generateSequence(x) { if (p[it] == it) null else p[it] }.toList().let { path -> path.last().also { r -> path.forEach { p[it] = r } } } fun countComponents(nums: IntArray, threshold: Int): Int = IntArray(threshold + 1) { it }.let { p -> nums.filter { it <= threshold }.forEach { x -> (2 * x..threshold step x).forEach { y -> p[find(p, x)] = find(p, y) } }.let { nums.count { it > threshold } + nums.filter { it <= threshold }.map { find(p, it) }.distinct().size } } }